query($cursor: String) {
  issues(first: 100, after: $cursor, orderBy: updatedAt) {
    nodes {
      id
      identifier
      title
      description
      priority
      priorityLabel
      state          { id name type color }
      team           { id name key }
      assignee       { id name email }
      creator        { id name email }
      project        { id name }
      cycle          { id name number }
      labels         { nodes { id name color } }
      parent         { id identifier title }
      estimate
      dueDate
      completedAt
      canceledAt
      autoClosedAt
      createdAt
      updatedAt
      archivedAt
      url
      branchName
      customerTicketCount
    }
    pageInfo {
      hasNextPage
      endCursor
    }
  }
}

